9487	# Takes <task>/.consult.write.lock (see the section comment): opened like .consult.lock and
9488	# retried with backoff (50 ms, doubling up to 1 s) while another process holds it, until
9489	# $TimeoutSec. { Acquired; Path; Stream; Record; Message; Waited (seconds); WaitedMs (whole
9490	# milliseconds, 0 when the lock was free at once) }; release with Exit-TaskLock (close the
9491	# handle; the file stays).
9492	function Enter-WriteLock {
9493	    param([string]$TaskDir, [string]$Task, [double]$TimeoutSec = 60)
9494	    $path = Join-Path $TaskDir '.consult.write.lock'
9495	    $share = if ($script:OnWindows) { [IO.FileShare]::Read } else { [IO.FileShare]::None }
9496	    $record = [pscustomobject]@{
9497	        pid        = $PID
9498	        start_time = (Get-ProcessStartIso -ProcessId $PID)
9499	        host       = [Environment]::MachineName
9500	        task       = $Task
9501	        started    = (Get-IsoTimestamp)
9502	    }
9503	    $watch = [System.Diagnostics.Stopwatch]::StartNew()
9504	    $delay = 50
9505	    $fs = $null
9506	    while ($null -eq $fs) {
9507	        try {
9508	            $fs = [IO.File]::Open($path, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, $share)
9509	        } catch [System.IO.DirectoryNotFoundException] {
9510	            $r = New-LockRefusal -Path $path -Message "could not open the write lock '$path': $($_.Exception.Message)"
9511	            $r | Add-Member -NotePropertyName 'Waited' -NotePropertyValue ([math]::Round($watch.Elapsed.TotalSeconds, 1))
